\section{Introduction}

\subsection{The problem}

For a smooth projective variety $X$ of dimension $n$ over $\mathbb{F}_q$, the zeta
function factors as an alternating product of polynomials
$P_i(T) = \det(1 - \mathrm{Frob}\,T \mid H^i)$, and the middle-degree factor
\[
P(T) = \prod_{i=1}^{d}(1-\alpha_i T), \qquad |\alpha_i| = q^{n/2},
\]
carries the essential arithmetic.  Poincar\'e duality acts on the multiset
$\{\alpha_i\}$ by $\alpha \mapsto q^n/\alpha$: concretely, there is a permutation
$\sigma$ of the index set with
\[
\alpha_i\,\alpha_{\sigma(i)} = q^n = Q^2, \qquad Q := q^{n/2}.
\]
Substituting $T \mapsto (Q^2T)^{-1}$ in $P$ produces a functional equation
\[
(Q^2T)^d\,P\bigl((Q^2T)^{-1}\bigr) = \varepsilon\,Q^d\,P(T),
\]
whose sign $\varepsilon = \pm1$ is the root number of the associated $L$-factor.  By the
parity philosophy, this sign governs the parity of the order of vanishing at the central
point.  The organising question is: \emph{when is $\prod_i \alpha_i$ exactly $Q^d$, with
no sign correction --- and what exactly is $\varepsilon$?}

\subsection{Results}

We answer this in four layers: the sign law and its sharp converse
(\S\ref{sec:signlaw}); the central-parity form, in which the permutation disappears
(\S\ref{sec:central}); structural properties making $\varepsilon$ a genuine invariant
(\S\ref{sec:structure}); and an exact bridge to an analytic parity statement
(\S\ref{sec:analytic}).  Section~\ref{sec:witnesses} gives sharpness witnesses,
\S\ref{sec:discussion} the discussion, and \S\ref{sec:future} open directions.

\subsection{Honest scope}

The object studied is an axiomatised model.  It records exactly the duality structure
the Weil conjectures supply --- $\sigma$ an involution with
$\alpha_i\alpha_{\sigma(i)} = Q^2$ --- over an arbitrary field.  Nothing about the
\emph{existence} of such systems for actual varieties, nor the Riemann-hypothesis bound
$|\alpha_i| = q^{n/2}$, is used or claimed.  The results are purely structural
consequences of duality and hence apply verbatim to any cohomological setting with a
perfect pairing into the Tate twist.

\section{Definitions}

Throughout, $K$ is a field and $\iota$ a finite index set with $d := |\iota|$.

\begin{definition}[Duality eigensystem]
A \emph{duality eigensystem} over $K$ on $\iota$ consists of a scalar $Q \in K$ with
$Q \neq 0$ (the \emph{half-weight}), a family $\alpha : \iota \to K$ (the
\emph{eigenvalues}), and a permutation $\sigma$ of $\iota$ (the \emph{duality
permutation}), subject to:
\begin{itemize}
\item \textbf{(Involutivity)} $\sigma(\sigma(i)) = i$ for all $i$;
\item \textbf{(Duality)} $\alpha_i \cdot \alpha_{\sigma(i)} = Q^2$ for all $i$.
\end{itemize}
We write $E = (Q,\alpha,\sigma)$ and call $d = |\iota|$ the \emph{degree}.
\end{definition}

\begin{definition}
The \emph{negative fixed set} is
$\NF(E) := \{ i : \sigma(i) = i,\ \alpha_i = -Q\}$, with $\nu := |\NF(E)|$.
The \emph{central multiplicity} is $m_+ := \#\{ i : \alpha_i = Q\}$.
The \emph{characteristic polynomial} is $P_E(T) := \prod_{i}(1 - \alpha_i T)$.
The \emph{root sign} is
\[
\varepsilon(E) := \frac{(-1)^d \prod_{i}\alpha_i}{Q^d}.
\]
\end{definition}

Theorem~\ref{thm:fe} shows that $\varepsilon(E)$ is precisely the constant appearing in
the duality functional equation, so the last definition is not arbitrary.

\begin{remark}
The two axioms are independent in the strongest sense:
Theorem~\ref{thm:threecycle} exhibits a bijective, fixed-point-free $\sigma$ satisfying
Duality but not Involutivity, for which the main conclusion fails.
\end{remark}

\section{The sign law}\label{sec:signlaw}

\subsection{Elementary consequences of duality}

\begin{lemma}\label{lem:nonzero}
For every $i$, $\alpha_i \neq 0$.
\end{lemma}
\begin{proof}
If $\alpha_i = 0$ then Duality gives $0 = Q^2$, contradicting $Q \neq 0$.
\end{proof}

\begin{lemma}\label{lem:fixedpm}
If $\sigma(i) = i$, then $\alpha_i = Q$ or $\alpha_i = -Q$.
\end{lemma}
\begin{proof}
Duality at $i$ reads $\alpha_i^2 = Q^2$, so $(\alpha_i - Q)(\alpha_i + Q) = 0$, and $K$
is a field.
\end{proof}

Geometrically, when $|\alpha_i| = Q$ these are exactly the two \emph{real} points of the
circle of radius $Q$: the eigenvalues that are their own duality partners.

\begin{lemma}[The failed naive route]\label{lem:naive}
Multiplying Duality over all $i$ and using that $\sigma$ is a bijection gives
$\bigl(\prod_i \alpha_i\bigr)^2 = Q^{2d}$, hence $\prod_i \alpha_i = \pm Q^d$.
\end{lemma}

This determines the product only up to sign --- precisely the information at stake.
Breaking the ambiguity requires the pairing argument below, and, crucially,
involutivity.

\subsection{Cancellation over two-cycles}

\begin{definition}
Set $\beta_i := 1$ if $\sigma(i) = i$, and $\beta_i := \alpha_i/Q$ otherwise.
\end{definition}

\begin{lemma}[Pairing cancellation]\label{lem:pairing}
$\prod_{i \in \iota} \beta_i = 1$.
\end{lemma}
\begin{proof}
Apply the involution-pairing principle for products.  The map $\sigma$ is an involution
of $\iota$.  For each $i$ with $\sigma(i) \neq i$,
$\beta_i\,\beta_{\sigma(i)} = (\alpha_i/Q)(\alpha_{\sigma(i)}/Q) = Q^2/Q^2 = 1$ by
Duality; for each fixed $i$, $\beta_i = 1$.  Every orbit therefore contributes $1$ to
the total product.
\end{proof}

This lemma is the heart of the matter: \emph{duality two-cycles are sign-neutral},
whatever their eigenvalues.

\subsection{The exact sign law}

\begin{theorem}[Duality sign law]\label{thm:signlaw}
For every duality eigensystem $E$,
\[
\prod_{i \in \iota} \alpha_i \;=\; (-1)^{\nu}\,Q^{d}, \qquad \nu = |\NF(E)|.
\]
\end{theorem}
\begin{proof}
We claim that for every $i$,
\[
\alpha_i = (Q\beta_i)\cdot\begin{cases}-1 & i \in \NF(E),\\ \phantom{-}1 &
\text{otherwise.}\end{cases}
\]
If $\sigma(i) \neq i$ then $\beta_i = \alpha_i/Q$ and $i \notin \NF(E)$, so
$Q\beta_i = \alpha_i$.  If $\sigma(i) = i$ then $\beta_i = 1$ and, by
Lemma~\ref{lem:fixedpm}, either $\alpha_i = Q$ with $i \notin \NF(E)$, or
$\alpha_i = -Q$ with $i \in \NF(E)$; in both cases the claim holds.  Taking the product
over $i$ and splitting the two factors,
\[
\prod_i \alpha_i = \Bigl(Q^d \prod_i \beta_i\Bigr)\cdot(-1)^{\nu} = (-1)^{\nu} Q^d
\]
by Lemma~\ref{lem:pairing}.
\end{proof}

\begin{corollary}[The conjecture, proved]\label{cor:mission}
If $\sigma(i) = i \implies \alpha_i \neq -Q$ for all $i$, then $\prod_i \alpha_i = Q^d$.
\end{corollary}

\begin{theorem}[Sharp converse]\label{thm:converse}
Suppose $-1 \neq 1$ in $K$.  Then $\prod_i \alpha_i = Q^d$ if and only if $\nu$ is even.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:signlaw}, $\prod\alpha_i = (-1)^\nu Q^d$ with $Q^d \neq 0$.  If
$\nu$ is even then $(-1)^\nu = 1$.  If $\nu$ is odd, then $-Q^d = Q^d$ would give
$-1 = 1$ after cancelling the unit $Q^d$.
\end{proof}

Thus the hypothesis of Corollary~\ref{cor:mission} is sufficient but not necessary; the
genuine invariant is a $\mathbb{Z}/2$ count of anti-diagonal fixed points, a
Lefschetz-style statement.  In characteristic $2$ the sign question is empty, which is
why $-1 \neq 1$ is assumed.

\subsection{The functional equation}

\begin{theorem}[Duality functional equation]\label{thm:fe}
For every $T \neq 0$,
\[
(Q^2T)^d\,P_E\bigl((Q^2T)^{-1}\bigr) \;=\; (-1)^d\Bigl(\prod_i \alpha_i\Bigr) P_E(T)
\;=\; \varepsilon(E)\,Q^d\,P_E(T).
\]
\end{theorem}
\begin{proof}
For each $i$,
\[
(Q^2T)\bigl(1 - \alpha_i (Q^2T)^{-1}\bigr) = Q^2T - \alpha_i
= -\alpha_i\Bigl(1 - \tfrac{Q^2}{\alpha_i}T\Bigr)
= -\alpha_i\bigl(1 - \alpha_{\sigma(i)}T\bigr),
\]
using Lemma~\ref{lem:nonzero} and Duality.  Taking the product over $i$, distributing
the $d$ copies of $Q^2T$, and using that $\sigma$ is a bijection (so
$\prod_i (1-\alpha_{\sigma(i)}T) = P_E(T)$), the claim follows from
$\prod_i(-\alpha_i) = (-1)^d\prod_i \alpha_i$ and the definition of $\varepsilon(E)$.
\end{proof}

This theorem uses only that $\sigma$ is a \emph{bijection} with
$\alpha_i\alpha_{\sigma(i)} = Q^2$; involutivity is needed only in
Theorem~\ref{thm:signlaw}, which evaluates the resulting constant.

\begin{theorem}[Closed formula for the sign]\label{thm:closedform}
$\varepsilon(E) = (-1)^{\,d + \nu}$.  In particular, if $\sigma$ has no $-Q$ fixed
point, $\varepsilon(E) = (-1)^d$.
\end{theorem}

\section{Central parity: eliminating the permutation}\label{sec:central}

The formula $\varepsilon = (-1)^{d+\nu}$ refers to $\sigma$, which is auxiliary data,
whereas the multiset $\{\alpha_i\}$ is intrinsic.  We now show $\varepsilon$ depends on
the multiset alone.

\begin{lemma}[Free involutions have even orbit count]\label{lem:even}
Let $g$ be an involution of a set and $S$ a finite subset with $g(S) \subseteq S$ and
$g(a) \neq a$ for all $a \in S$.  Then $|S|$ is even.
\end{lemma}
\begin{proof}
Evaluate $\prod_{a\in S}(-1)$ by pairing $a$ with $g(a)$: each two-element orbit
contributes $(-1)(-1) = 1$ and there are no fixed points, so the product is $1$.  It is
also $(-1)^{|S|}$; hence $|S|$ is even.
\end{proof}

\begin{lemma}\label{lem:stable}
If $\alpha_i = Q$ then $\alpha_{\sigma(i)} = Q$.  Consequently both
$\{i : \sigma(i)\neq i\}$ and $\{i : \sigma(i) \neq i,\ \alpha_i = Q\}$ have even
cardinality.
\end{lemma}
\begin{proof}
Duality gives $Q\,\alpha_{\sigma(i)} = Q^2$; divide by $Q \neq 0$.  For the second
claim, apply Lemma~\ref{lem:even} with $g = \sigma$: $\sigma$ maps non-fixed indices to
non-fixed indices (if $\sigma(\sigma(i)) = \sigma(i)$, applying $\sigma$ and
involutivity gives $\sigma(i) = i$) and has no fixed point there; the first part shows
the central subset is $\sigma$-stable.
\end{proof}

\begin{proposition}[Counting bridge]\label{prop:bridge}
If $-1 \neq 1$ in $K$, then $d + \nu + m_+$ is even.
\end{proposition}
\begin{proof}
First $Q \neq -Q$: otherwise $2Q = 0$, and $Q \neq 0$ forces $2 = 0$, i.e.\ $-1 = 1$.
Hence by Lemma~\ref{lem:fixedpm} a fixed index has $\alpha_i = -Q$ exactly when
$\alpha_i \neq Q$, so $\NF(E) = \{i : \sigma(i)=i,\ \alpha_i \neq Q\}$.  Write
$F := \{i:\sigma(i)=i\}$, $R := \{i : \sigma(i)\neq i\}$,
$F_+ := \{i \in F : \alpha_i = Q\}$, $R_+ := \{i\in R:\alpha_i = Q\}$.  Then
$d = |F| + |R|$, $|F| = |F_+| + \nu$, and $m_+ = |F_+| + |R_+|$, whence
\[
d + \nu + m_+ = 2|F_+| + 2\nu + |R| + |R_+|,
\]
which is even because $|R|$ and $|R_+|$ are even by Lemma~\ref{lem:stable}.
\end{proof}

\begin{theorem}[Central parity law]\label{thm:centralparity}
If $-1 \neq 1$ in $K$, then $\varepsilon(E) = (-1)^{m_+}$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:closedform}, $\varepsilon = (-1)^{d+\nu}$; by
Proposition~\ref{prop:bridge}, $d+\nu \equiv m_+ \pmod 2$; powers of $-1$ with exponents
of equal parity agree.
\end{proof}

\begin{proposition}[Central factorisation and exactness]\label{prop:factor}
Let $G_E(T) := \prod_{\alpha_i \neq Q}(1 - \alpha_i T)$.  Then
$P_E(T) = (1 - QT)^{m_+}\,G_E(T)$ for all $T$, and $G_E(Q^{-1}) \neq 0$.
\end{proposition}
\begin{proof}
Split $\prod_i(1-\alpha_iT)$ over $\{\alpha_i = Q\}$ and its complement; on the first
set every factor equals $1-QT$, and there are $m_+$ of them.  A factor
$1 - \alpha_i Q^{-1}$ vanishes exactly when $\alpha_i = Q$, which is excluded on the
index set of $G_E$; a product of nonzero field elements is nonzero.
\end{proof}

Thus $m_+$ is \emph{exactly} the order of vanishing of $P_E$ at the central point
$T = Q^{-1}$, and Theorem~\ref{thm:centralparity} reads: \emph{the sign of the
functional equation is $(-1)^{\text{order of vanishing at the centre}}$}.

\begin{corollary}[Parity criterion and central vanishing]\label{cor:vanish}
Suppose $-1 \neq 1$ in $K$.  Then $\varepsilon(E) = -1$ if and only if $m_+$ is odd; and
in that case $P_E(Q^{-1}) = 0$.  If moreover $\sigma$ has no $-Q$ fixed point, then
$(-1)^{m_+} = (-1)^d$.
\end{corollary}
\begin{proof}
The equivalence is Theorem~\ref{thm:centralparity} together with $-1 \neq 1$.  If $m_+$
is odd it is positive, so $P_E(Q^{-1}) = 0^{m_+}G_E(Q^{-1}) = 0$ by
Proposition~\ref{prop:factor}.  The last claim combines
Theorems~\ref{thm:centralparity} and~\ref{thm:closedform}.
\end{proof}

\section{Structural properties: $\varepsilon$ as an invariant}\label{sec:structure}

\begin{theorem}\label{thm:mu2}
$\varepsilon(E)^2 = 1$ for every duality eigensystem.
\end{theorem}
\begin{proof}
$\varepsilon = (-1)^{d+\nu}$ by Theorem~\ref{thm:closedform}, and
$\bigl((-1)^{k}\bigr)^2 = 1$.
\end{proof}

\begin{definition}[Direct sum]
Given eigensystems $E$ on $\iota$ and $F$ on $\iota'$ with the \emph{same} half-weight
$Q$, define $E \oplus F$ on the disjoint union $\iota \sqcup \iota'$ by concatenating
the eigenvalue families and letting the duality permutation act blockwise.  The axioms
are inherited componentwise.
\end{definition}

Equal $Q$ is essential: eigensystems of different weights cannot be summed --- that
would be a graded, not a direct, sum (\S\ref{sec:future}).

\begin{proposition}\label{prop:sumbasics}
$\deg(E\oplus F) = \deg E + \deg F$; $P_{E\oplus F} = P_E P_F$;
$\prod_{E\oplus F}\alpha = \bigl(\prod_E\alpha\bigr)\bigl(\prod_F\alpha\bigr)$;
and $m_+(E\oplus F) = m_+(E) + m_+(F)$.
\end{proposition}

\begin{theorem}[Multiplicativity]\label{thm:mult}
$\varepsilon(E \oplus F) = \varepsilon(E)\,\varepsilon(F)$.
\end{theorem}
\begin{proof}
By the definition of $\varepsilon$ and Proposition~\ref{prop:sumbasics},
\[
\varepsilon(E\oplus F)
= \frac{(-1)^{d_E+d_F}\bigl(\prod_E\alpha\bigr)\bigl(\prod_F\alpha\bigr)}{Q^{d_E+d_F}}
= \frac{(-1)^{d_E}\prod_E\alpha}{Q^{d_E}}\cdot\frac{(-1)^{d_F}\prod_F\alpha}{Q^{d_F}}.
\qedhere
\]
\end{proof}

So $E \mapsto \varepsilon(E)$ is a monoid homomorphism from duality eigensystems of
fixed weight into $\mu_2$ --- the model's shadow of the multiplicativity of root numbers
in the Grothendieck group of Galois representations.  The hypothesis ``no $-Q$ fixed
point'' is likewise stable under direct sums.

\begin{definition}[Twist]
For $c \neq 0$, the \emph{twist} $E^{(c)}$ has half-weight $cQ$, eigenvalues
$c\alpha_i$, and the same $\sigma$.  Duality holds since
$(c\alpha_i)(c\alpha_{\sigma(i)}) = (cQ)^2$.
\end{definition}

\begin{theorem}[Twist invariance]\label{thm:twist}
$\varepsilon(E^{(c)}) = \varepsilon(E)$ for every $c \neq 0$.
\end{theorem}
\begin{proof}
$\prod_i(c\alpha_i) = c^d\prod_i\alpha_i$ and $(cQ)^d = c^dQ^d$; the factors $c^d$
cancel.
\end{proof}

Hence $\varepsilon$ depends only on the \emph{normalised} eigenvalues $\alpha_i/Q$.

\begin{theorem}[Odd degree]\label{thm:odd}
If $d$ is odd, then $\sigma$ has a fixed point.  If moreover $\sigma$ has no $-Q$ fixed
point then $\varepsilon(E) = -1$; and if in addition $-1 \neq 1$ in $K$, then
$P_E(Q^{-1}) = 0$.
\end{theorem}
\begin{proof}
If $\sigma$ had no fixed point, $\iota$ would be the set of non-fixed indices, which is
even by Lemma~\ref{lem:stable}, contradicting $d$ odd.  The second claim is
Theorem~\ref{thm:closedform} with $d$ odd; the third is
Corollary~\ref{cor:vanish}.
\end{proof}

This is the model's counterpart of ``root number $-1$ implies the central value
vanishes'': odd degree forces a fixed point, the hypothesis forces it to carry $+Q$,
hence $m_+$ is odd.

\section{The analytic bridge}\label{sec:analytic}

We now take $K = \mathbb{C}$ and convert the polynomial functional equation into an
analytic one.

\begin{theorem}[Taylor symmetry]\label{thm:taylor}
Let $\Lambda$ be analytic at $s = 1$, not identically zero in any neighbourhood of $1$,
and suppose $\Lambda(2-s) = w\,\Lambda(s)$ near $1$, with $w$ constant.  Let
$r := \ord_{s=1}\Lambda$.  Then $(-1)^{r} = w$.
\end{theorem}
\begin{proof}
Write $\Lambda(1+u) = \sum_{k\ge0}c_k u^k$ near $u = 0$; some $c_k \neq 0$, and $r$ is
the least such index.  Substituting $s = 1+u$ turns the functional equation into
$\Lambda(1-u) = w\,\Lambda(1+u)$, i.e.\
$\sum_k c_k(-1)^ku^k = w\sum_k c_ku^k$.  Comparing coefficients gives
$(-1)^kc_k = wc_k$ for all $k$; taking $k = r$ and dividing by $c_r \neq 0$ yields
$(-1)^r = w$.
\end{proof}

Fix a complex logarithm $L$ of the half-weight, i.e.\ $e^L = Q$.

\begin{definition}[Completed function]
\[
\Lambda_E(s) := \exp\!\Bigl(\tfrac{(s-1)d}{2}L\Bigr)\cdot P_E\bigl(e^{-sL}\bigr).
\]
\end{definition}

The substitution $T = e^{-sL}$ carries $T \mapsto (Q^2T)^{-1}$ to the reflection
$s \mapsto 2-s$, since $Q^2 e^{-sL} = e^{(2-s)L}$; the central point $T = Q^{-1}$
corresponds to $s = 1$.  The exponential prefactor is the model's analogue of the
conductor factor $N^{s/2}$ in the completed Hasse--Weil $L$-function.  As a product and
composition of entire functions, $\Lambda_E$ is entire.

\begin{theorem}[Analytic functional equation]\label{thm:analyticfe}
For every $s \in \mathbb{C}$, $\Lambda_E(2-s) = \varepsilon(E)\cdot\Lambda_E(s)$.
\end{theorem}
\begin{proof}
Put $T := e^{-sL} \neq 0$.  Then $Q^2T = e^{(2-s)L}$, hence
$(Q^2T)^{-1} = e^{-(2-s)L}$, $(Q^2T)^d = e^{(2-s)Ld}$ and $Q^d = e^{Ld}$.
Theorem~\ref{thm:fe} at $T$ reads
$e^{(2-s)Ld}P_E\bigl(e^{-(2-s)L}\bigr) = \varepsilon e^{Ld}P_E(T)$, so dividing by the
nonvanishing factor $e^{(2-s)Ld}$,
\[
\Lambda_E(2-s) = e^{\frac{(1-s)d}{2}L}P_E\bigl(e^{-(2-s)L}\bigr)
= \varepsilon\;e^{\left(\frac{(1-s)d}{2} + d - (2-s)d\right)L}P_E(T).
\]
The exponent bookkeeping is $\frac{(1-s)d}{2} + d - (2-s)d = \frac{(s-1)d}{2}$, so the
right-hand side is $\varepsilon\,\Lambda_E(s)$.
\end{proof}

\begin{remark}[Independence of the branch]
The logarithm $L$ is a choice; any $L' = L + 2\pi i k$ also satisfies $e^{L'} = Q$, and
Theorem~\ref{thm:analyticfe} holds verbatim for the corresponding $\Lambda'_E$ with the
\emph{same} constant $\varepsilon(E)$, which is defined without reference to $L$.  The
parity conclusion below is therefore independent of the branch.  Nothing requires $Q$ to
be real or positive.
\end{remark}

\begin{theorem}[Analytic parity]\label{thm:analyticparity}
Suppose $\Lambda_E$ is not identically zero near $s=1$, and set
$r := \ord_{s=1}\Lambda_E$.  Then
\[
(-1)^{r} = \varepsilon(E) = (-1)^{m_+}.
\]
If moreover no fixed point of $\sigma$ carries $\alpha = -Q$, then $(-1)^{r} = (-1)^d$;
in particular odd degree forces $\Lambda_E$ to vanish at the central point.
\end{theorem}
\begin{proof}
Combine Theorems~\ref{thm:analyticfe} and~\ref{thm:taylor} with $w = \varepsilon(E)$,
then Theorem~\ref{thm:centralparity} (over $\mathbb{C}$, $-1 \neq 1$), then
Theorem~\ref{thm:closedform}.
\end{proof}

\begin{proposition}
If $P_E\bigl(e^{-s_0L}\bigr) \neq 0$ for some $s_0$, then $\Lambda_E(s_0) \neq 0$, so
$\Lambda_E$ is not the zero function and $r$ is finite.
\end{proposition}

In practice this is automatic: $P_E(0) = 1$, so $P_E$ is not the zero polynomial and has
finitely many roots, while $s \mapsto e^{-sL}$ is onto $\mathbb{C}^\times$ when
$L \neq 0$.

Theorem~\ref{thm:analyticparity} is the culmination: an \emph{analytic} invariant --- the
order of vanishing of a transcendental function --- is computed modulo $2$ by a
\emph{finite count} of Frobenius eigenvalues.

\section{Sharpness: explicit witnesses}\label{sec:witnesses}

All witnesses are over $\mathbb{C}$, with $Q \neq 0$ arbitrary.

\begin{theorem}[Degree $1$]\label{thm:deg1}
With $d=1$, $\sigma = \id$: if $\alpha_1 = Q$ then the no-$(-Q)$ hypothesis holds,
$\prod\alpha = Q$, and $\varepsilon = -1 = (-1)^1$, as predicted.  If instead
$\alpha_1 = -Q$ then $\prod\alpha = -Q \neq Q$ and $\varepsilon = +1 \neq (-1)^1$.
\end{theorem}

Hence a \emph{single} anti-diagonal fixed point flips the sign, and the hypothesis of
Corollary~\ref{cor:mission} cannot be deleted.

\begin{theorem}[Degree $2$]\label{thm:deg2}
With $d=2$ and $\sigma$ the transposition and $\alpha = (a, Q^2/a)$, $a \neq 0$: there
are no fixed points, $\prod\alpha = Q^2$, and $\varepsilon = +1 = (-1)^2$, for every
$a$.  With $\sigma = \id$ and $\alpha_1 = \alpha_2 = -Q$: the hypothesis fails at every
index ($\nu = 2$), yet $\prod\alpha = Q^2$ and $\varepsilon = +1$.
\end{theorem}

So two-cycles never contribute to the sign, and two anti-diagonal fixed points cancel:
the hypothesis is sufficient but not necessary, in accordance with
Theorem~\ref{thm:converse}.

\begin{theorem}[Degree $4$]\label{thm:deg4}
With $\sigma$ a product of two transpositions and $\alpha = (a, Q^2/a, b, Q^2/b)$,
$a,b\neq0$: $\prod\alpha = Q^4$ and $\varepsilon = +1 = (-1)^4$.  With $\sigma$ the
transposition of the last two indices and $\alpha = (Q, -Q, a, Q^2/a)$:
$\prod\alpha = -Q^4$ and $\varepsilon = -1 \neq (-1)^4$.
\end{theorem}

The sign is thus genuinely a function of the fixed-point data, not of the degree alone.
Since $\varepsilon$ depends only on $d$ and the fixed-point data
(Theorem~\ref{thm:closedform}), degree $4$ already exhibits every combinatorial pattern
of an involution.

\begin{theorem}[Involutivity is essential]\label{thm:threecycle}
Let $\iota = \{0,1,2\}$, let $\sigma$ be the $3$-cycle $i \mapsto i+1 \pmod 3$, and let
$\alpha_i = -Q$ for all $i$.  Then $\sigma$ is a bijection, Duality holds
($(-Q)(-Q) = Q^2$), $\sigma$ has \emph{no} fixed point (so the hypothesis of
Corollary~\ref{cor:mission} holds vacuously), $\sigma$ is not an involution, and
\[
\prod_i \alpha_i = -Q^3 \neq Q^3 .
\]
The functional-equation constant is $(-1)^{d+1}$, not $(-1)^d$.
\end{theorem}

Hence $\sigma\circ\sigma = \id$ cannot be weakened to ``$\sigma$ is a bijection''; it is
exactly what Lemma~\ref{lem:pairing} consumes.  The shape of the witness is forced:
chasing $\alpha_i\alpha_{\sigma(i)} = Q^2$ around a $3$-cycle gives
$\alpha_0\alpha_1 = \alpha_1\alpha_2 = \alpha_2\alpha_0 = Q^2$, whence
$\alpha_0 = \alpha_2$ and $\alpha_0^2 = Q^2$, so the cycle is constant $\pm Q$.

\section{Discussion}\label{sec:discussion}

\subsection{What is being asserted}
For a multiset of scalars stable under the reflection $\alpha \mapsto Q^2/\alpha$, the
functional-equation sign is determined entirely by the fixed points of that reflection,
and there only by their parity.  All the complexity of a generic eigenvalue is invisible
to the sign, because the reflection pairs it with an exact reciprocal.  This is why
parity statements are so much more tractable than the exact-order statements they
shadow: the full conjecture asks for a number, whereas parity asks only for a bit, and
that bit is protected by a symmetry rigid enough to compute it exactly.

\subsection{Computational content}
The sign law yields an algorithm of striking simplicity: count the multiplicity $m_+$ of
$Q$ in the eigenvalue list and return $(-1)^{m_+}$.  This runs in $O(d)$ operations and
requires \emph{no knowledge of $\sigma$}.  If $\sigma$ is given, one may instead compute
$(-1)^{d+\nu}$; agreement of the two computations is a nontrivial verification of the
duality structure and detects, for instance, non-involutive $\sigma$
(Theorem~\ref{thm:threecycle}).

\subsection{Relations to classical statements}
The invariant $\varepsilon$ is the model's root number: $\mu_2$-valued
(Theorem~\ref{thm:mu2}), multiplicative (Theorem~\ref{thm:mult}), twist-invariant
(Theorem~\ref{thm:twist}).  Corollary~\ref{cor:vanish} is the statement
``$\varepsilon = -1 \Rightarrow$ central vanishing'', proved rather than conjectured;
Theorem~\ref{thm:odd} is the analogue of the guarantee of a point of infinite order when
the root number is $-1$; and Theorem~\ref{thm:analyticparity} shows the archimedean
Taylor-symmetry computation of parity and the finite-field fixed-point count are
literally the same element of $\mathbb{Z}/2$.

\subsection{Limits of the model}
Nothing here proves the \emph{existence} of duality eigensystems for a given variety;
the Riemann-hypothesis bound $|\alpha_i| = q^{n/2}$ is never used; and the model treats
a single self-paired block rather than a graded family paired across the middle.

\section{Future directions}\label{sec:future}

\subsection{Graded duality and the global zeta functional equation}
\begin{conjecture}
Let $H^0,\dots,H^{2n}$ be duality eigensystems in which Poincar\'e duality pairs $H^i$
with $H^{2n-i}$, with weights $|\alpha| = q^{i/2}$.  Then the global zeta function
$Z(T) = \prod_i P_i(T)^{(-1)^{i+1}}$ satisfies
$Z\bigl(1/(q^nT)\bigr) = \pm q^{n\chi/2}T^{\chi}Z(T)$ with
$\chi = \sum_i(-1)^ib_i$, and the sign is $(-1)^{m_+(n)}$: it is carried entirely by the
middle cohomology.
\end{conjecture}
Off-middle degrees pair with a \emph{different} block, so their contribution to the sign
telescopes and only the self-paired middle block can produce a fixed point.  The proof
of Theorem~\ref{thm:signlaw} already isolates the sign in the fixed-point set, and
Theorem~\ref{thm:mult} shows how blocks compose.

\subsection{Weight-constrained rigidity}
\begin{conjecture}
Impose $|\alpha_i| = Q$ with $Q > 0$ real.  Then duality is forced: $\sigma$ may be
taken to be complex conjugation, every fixed point is real,
$m_+ + m_- \equiv d \pmod 2$, and $\varepsilon = (-1)^{m_+}$ with $m_+ + m_-$ the number
of real eigenvalues.  Consequently the number of admissible sign patterns in degree $d$
is exactly $\lfloor d/2\rfloor + 1$.
\end{conjecture}
The Riemann-hypothesis bound turns the abstract duality permutation into the canonical
involution $\alpha \mapsto Q^2/\alpha = \overline{\alpha}$, converting a combinatorial
hypothesis into a topological one.

\subsection{Further questions}
Higher $\mu_k$ analogues (replacing the involution by an order-$k$ symmetry
$\alpha \mapsto \zeta Q^2/\alpha$); local constancy of $\varepsilon$ in algebraic
families and the loci where an eigenvalue collides with $\pm Q$; effective bounds on
$m_+$ itself from finitely many point counts, upgrading parity to a rank bound; and
eigensystems over integral domains, connecting the theory to integral structures on
cohomology.

